package com.aiservice.presentation.controller;
import com.aiservice.application.service.TextbookStructureService;import com.aiservice.presentation.response.ApiResponse;import jakarta.validation.Valid;import java.io.*;import java.util.*;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/textbook-structures") @PreAuthorize("hasRole('SUBJECT_ADMIN')") public class TextbookStructureController{private final TextbookStructureService service;public TextbookStructureController(TextbookStructureService service){this.service=service;}@PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE)public ApiResponse<TextbookStructureService.View>upload(@AuthenticationPrincipal Jwt jwt,@RequestParam UUID subjectId,@RequestPart("file")MultipartFile file)throws IOException{return ApiResponse.ok(service.upload(user(jwt),subjectId,file.getOriginalFilename(),file.getContentType(),file.getSize(),file.getInputStream()));}@GetMapping public ApiResponse<List<TextbookStructureService.View>>list(@AuthenticationPrincipal Jwt jwt,@RequestParam UUID subjectId){return ApiResponse.ok(service.list(user(jwt),subjectId));}@GetMapping("/{id}")public ApiResponse<TextbookStructureService.View>get(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){return ApiResponse.ok(service.get(id,user(jwt)));}@PutMapping("/{id}/confirm")public ApiResponse<TextbookStructureService.View>confirm(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt,@RequestBody TextbookStructureService.Structure structure){return ApiResponse.ok(service.confirm(id,user(jwt),structure,jwt.getTokenValue()));}@GetMapping("/{id}/source")public ResponseEntity<InputStreamResource>source(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){var source=service.source(id,user(jwt));return ResponseEntity.ok().contentType(MediaType.APPLICATION_PDF).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+source.filename().replace("\"","")+"\"").body(new InputStreamResource(source.data()));}private UUID user(Jwt jwt){return UUID.fromString(jwt.getSubject());}}
